            ]}>
              {connection?.status === 'pending' ? 'Pending' : 'Connect'}
            </Text>
          </TouchableOpacity>
        )}
      </View>

      <View style={styles.wardrobeSection}>
        <Text style={[styles.sectionTitle, { color: colors.text }]}>Wardrobe</Text>
        {wardrobeLoading ? (
          <ActivityIndicator color={colors.tint} style={{ marginTop: Spacing.xl }} />
